// Üç giriş de buradan geçer:
//  • POST /webhook/butce → alanlar "body" içinde ({"metin": "limit 20000"}),
//  • GET  /webhook/butce → gövde yok, durum JSON olarak döner,
//  • Workflow 05'in /butce komutu → alanlar doğrudan gelir.
const j = $input.first().json || {};
const webhooktan = Object.prototype.hasOwnProperty.call(j, 'body') || Object.prototype.hasOwnProperty.call(j, 'query');
const govde = webhooktan ? (j.body && typeof j.body === 'object' ? j.body : {}) : j;

const chat_id = govde.chat_id ? String(govde.chat_id) : '';
const ISLEMLER = { durum: 'durum', limit: 'limit', anahtar: 'anahtar', kelime: 'anahtar', sil: 'sil' };
const metin = String(govde.metin || '').trim();
const ilk = metin.split(/\s+/)[0].toLowerCase();
let islem = 'durum';
let arg = '';
if (metin) {
  islem = ISLEMLER[ilk] || 'bilinmeyen';
  arg = ISLEMLER[ilk] ? metin.slice(ilk.length).trim() : metin;
}

return [{ json: { islem, arg, chat_id, webhooktan } }];

// ── Ortak: bütçe dosyası + bu ayın harcamaları → durum ───────────────────────
// harcamalar.json YALNIZCA okunur (07 ve 05 yazar); bu workflow ona dokunmaz.
const _okuDurumu = (okuNode, cikarNode) => {
  const okuHata = $(okuNode).first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  const cikarHata = $(cikarNode).first().json.error;
  const yok = /ENOENT|no such file|not found/i.test(okuMesaj);
  const bozuk = !yok && Boolean(okuHata || cikarHata);
  const mesaj = okuMesaj || String((cikarHata && (cikarHata.message || cikarHata)) || '');
  const j = $(cikarNode).first().json || {};
  return { yok, bozuk, mesaj, veri: (yok || bozuk) ? {} : (j.data || j) };
};
const kucuk = (s) => String(s || '').toLocaleLowerCase('tr-TR');
const tl = (n) => Number(n).toLocaleString('tr-TR', { maximumFractionDigits: 0 }) + ' TL';
const iki = (n) => String(n).padStart(2, '0');
const ayAnahtari = (d) => d.getFullYear() + '-' + iki(d.getMonth() + 1);

// "149,90" · "1.250" · "20000" · "20.000,00" → sayı
const sayiyaCevir = (ham) => {
  let t = String(ham).trim();
  const sonNokta = t.lastIndexOf('.');
  const sonVirgul = t.lastIndexOf(',');
  if (sonVirgul > sonNokta) t = t.replace(/\./g, '').replace(',', '.');
  else if (sonVirgul === -1 && /^\d{1,3}(\.\d{3})+$/.test(t)) t = t.replace(/\./g, '');
  else t = t.replace(/,/g, '');
  const n = Number(t);
  return Number.isFinite(n) ? n : null;
};

const butceyiDuzenle = (v) => ({
  aylikLimit: typeof v.aylikLimit === 'number' && v.aylikLimit > 0 ? v.aylikLimit : null,
  kategoriler: (Array.isArray(v.kategoriler) ? v.kategoriler : [])
    .filter((k) => k && String(k.ad || '').trim())
    .map((k) => ({
      ad: String(k.ad).trim(),
      limit: typeof k.limit === 'number' && k.limit > 0 ? k.limit : null,
      anahtarlar: (Array.isArray(k.anahtarlar) ? k.anahtarlar : []).map(kucuk).filter(Boolean),
    })),
  uyarilar: {
    ay: (v.uyarilar && v.uyarilar.ay) || null,
    gonderilen: (v.uyarilar && Array.isArray(v.uyarilar.gonderilen)) ? [...v.uyarilar.gonderilen] : [],
  },
});

// Harcamanın konusu + göndereni içinde anahtar kelime (ya da kategori adı)
// geçen ilk kategori kazanır. Hiçbiri tutmazsa "Diğer".
