  const metin = kucuk((h.konu || '') + ' ' + (h.kimden || ''));
  const k = kategoriler.find((x) => [kucuk(x.ad), ...x.anahtarlar].some((a) => a && metin.includes(a)));
  return k ? k.ad : 'Diğer';
};

const durumHesapla = (butce, harcamalar, simdi) => {
  const ay = ayAnahtari(simdi);
  const ayGun = new Date(simdi.getFullYear(), simdi.getMonth() + 1, 0).getDate();
  const gun = simdi.getDate();
  const buAy = harcamalar.filter((h) => {
    if (!h || typeof h.tutar !== 'number' || (h.paraBirimi && h.paraBirimi !== 'TL')) return false;
    const t = new Date(h.tarih);
    return !isNaN(t.getTime()) && ayAnahtari(t) === ay;
  });
  const toplamlar = new Map();
  for (const h of buAy) {
    const k = kategoriBul(h, butce.kategoriler);
    toplamlar.set(k, (toplamlar.get(k) || 0) + h.tutar);
  }
  const toplam = buAy.reduce((t, h) => t + h.tutar, 0);
  const oran = (x, limit) => (limit ? Math.round((x / limit) * 100) : null);
  const kalanGun = ayGun - gun + 1;
  const genel = {
    ad: 'Genel', limit: butce.aylikLimit, harcanan: toplam, oran: oran(toplam, butce.aylikLimit),
    kalan: butce.aylikLimit ? butce.aylikLimit - toplam : null,
    gunlukKalan: butce.aylikLimit ? Math.max(0, (butce.aylikLimit - toplam) / kalanGun) : null,
  };
  const kategoriler = butce.kategoriler.map((k) => {
    const harcanan = toplamlar.get(k.ad) || 0;
    return { ad: k.ad, limit: k.limit, harcanan, oran: oran(harcanan, k.limit) };
  });
  const diger = toplamlar.get('Diğer') || 0;
  return {
    ay, ayGun, gun, kayit: buAy.length, genel, kategoriler, diger,
    tahmin: gun > 0 ? Math.round((toplam / gun) * ayGun) : toplam,
  };
};

const cubuk = (oran) => {
  const dolu = Math.max(0, Math.min(10, Math.round((oran || 0) / 10)));
  return '▓'.repeat(dolu) + '░'.repeat(10 - dolu);
};
const ayAdi = (d) => d.toLocaleDateString('tr-TR', { month: 'long', year: 'numeric' });

