  const s = ['🎯 Bütçe — ' + ayAdi(simdi) + ' (' + d.gun + '/' + d.ayGun + '. gün, ' + d.kayit + ' kayıt)'];
  if (d.genel.limit) {
    s.push('Genel ' + cubuk(d.genel.oran) + ' %' + d.genel.oran);
    s.push('  ' + tl(d.genel.harcanan) + ' / ' + tl(d.genel.limit) + ' · ' +
      (d.genel.kalan >= 0 ? 'kalan ' + tl(d.genel.kalan) + ' · günde ' + tl(d.genel.gunlukKalan)
                          : '⚠️ ' + tl(-d.genel.kalan) + ' aşıldı'));
  } else {
    s.push('Bu ay: ' + tl(d.genel.harcanan) + ' (genel limit yok → /butce limit 20000)');
  }
  const satirlar = d.kategoriler
    .filter((k) => k.limit || k.harcanan > 0)
    .map((k) => k.limit
      ? '• ' + k.ad + ' ' + cubuk(k.oran) + ' %' + k.oran + ' — ' + tl(k.harcanan) + ' / ' + tl(k.limit)
      : '• ' + k.ad + ': ' + tl(k.harcanan) + ' (limitsiz)');
  if (d.diger > 0) satirlar.push('• Diğer: ' + tl(d.diger));
  if (satirlar.length) s.push('', 'Kategoriler:', ...satirlar);
  const asim = d.genel.limit && d.tahmin > d.genel.limit ? ' ⚠️ limitin üstünde' : '';
  s.push('', 'Ay sonu tahmini: ' + tl(d.tahmin) + asim);
  return s.join('\n');
};
// ─────────────────────────────────────────────────────────────────────────────
// Komut: durum / limit / anahtar / sil. Bütçe dosyası bozuksa durur — aksi
// hâlde varsayılanlarla üzerine yazılır ve kategoriler kaybolur. Harcama
// dosyası bozuksa yalnızca uyarılır (bu workflow ona yazmaz).
const b = _okuDurumu('Bütçeyi Oku', 'Bütçeyi Çıkar');
if (b.bozuk) throw new Error('butce.json okunamadı; veri kaybını önlemek için durduruldu → ' + b.mesaj);
const h = _okuDurumu('Harcamaları Oku (Bütçe)', 'Harcamaları Çıkar (Bütçe)');

const istek = $('İsteği Al (Bütçe)').first().json;
const butce = butceyiDuzenle(b.veri);
const harcamalar = Array.isArray(h.veri.harcamalar) ? h.veri.harcamalar : [];
const simdi = new Date();

let mesaj = '';
let yazilsin = false;
let hata = false;
const kategori = (ad) => butce.kategoriler.find((k) => kucuk(k.ad) === kucuk(ad));

const a = istek.arg;
if (istek.islem === 'durum') {
  mesaj = '';
} else if (istek.islem === 'limit') {
  // "limit 20000" · "limit Market 6000" · "limit Market 0" (limiti kaldırır)
  const m = a.match(/^(.*?)\s*([0-9][0-9.,]*)\s*(?:tl|₺)?$/i);
  const tutar = m ? sayiyaCevir(m[2]) : null;
  if (!m || tutar === null || tutar < 0) {
    hata = true;
    mesaj = 'Kullanım: /butce limit 20000  ·  /butce limit Market 6000';
  } else if (!m[1].trim()) {
    butce.aylikLimit = tutar > 0 ? tutar : null;
    yazilsin = true;
    mesaj = tutar > 0 ? '✅ Aylık genel limit: ' + tl(tutar) : '✅ Genel limit kaldırıldı.';
  } else {
    const ad = m[1].trim();
    let k = kategori(ad);
    if (!k) {
      k = { ad, limit: null, anahtarlar: [kucuk(ad)] };
      butce.kategoriler.push(k);
    }
    k.limit = tutar > 0 ? tutar : null;
    yazilsin = true;
    mesaj = '✅ ' + k.ad + ' limiti: ' + (k.limit ? tl(k.limit) : 'yok') +
      (k.anahtarlar.length ? '\nEşleşen kelimeler: ' + k.anahtarlar.join(', ') : '') +
      '\nKelime eklemek için: /butce anahtar ' + k.ad + ' migros';
  }
} else if (istek.islem === 'anahtar') {
  // Kategori adı birden çok kelime olabilir ("Yeme içme"): en uzun eşleşen ad seçilir.
  const k = butce.kategoriler
    .filter((x) => kucuk(a).startsWith(kucuk(x.ad) + ' '))
    .sort((x, y) => y.ad.length - x.ad.length)[0] || null;
  const yeni = k ? a.slice(k.ad.length).split(/\s*,\s*|\s+/).map(kucuk).filter(Boolean) : [];
  if (!k || yeni.length === 0) {
    hata = true;
    mesaj = 'Kullanım: /butce anahtar Market migros,a101\n' +
      (butce.kategoriler.length ? 'Kategoriler: ' + butce.kategoriler.map((x) => x.ad).join(', ') : 'Önce: /butce limit Market 6000');
  } else {
    k.anahtarlar = [...new Set([...k.anahtarlar, ...yeni])];
    yazilsin = true;
    mesaj = '✅ ' + k.ad + ' kelimeleri: ' + k.anahtarlar.join(', ');
  }
} else if (istek.islem === 'sil') {
  const k = kategori(a);
  if (!k) {
    hata = true;
    mesaj = '"' + a + '" diye bir kategori yok.';
  } else {
    butce.kategoriler.splice(butce.kategoriler.indexOf(k), 1);
    yazilsin = true;
    mesaj = '🗑 Kategori silindi: ' + k.ad + ' (harcamaları artık "Diğer"de)';
  }
} else {
  hata = true;
  mesaj = [
    'Bütçe komutları:',
    '• /butce → bu ayın durumu',
    '• /butce limit 20000 → aylık genel limit',
    '• /butce limit Market 6000 → kategori limiti',
    '• /butce anahtar Market migros,a101',
    '• /butce sil Market',
  ].join('\n');
}

const durum = durumHesapla(butce, harcamalar, simdi);
if (!hata) {
  mesaj = (mesaj ? mesaj + '\n\n' : '') + durumMetni(durum, simdi);
  if (h.bozuk) mesaj += '\n\n⚠️ harcamalar.json okunamadı: ' + h.mesaj;
}

return [{
  json: {
    islem: istek.islem, chat_id: istek.chat_id, webhooktan: istek.webhooktan,
    mesaj, hata, durum, yazilsin, butce,
  },
}];

// Yanıt düğümü yalnızca webhook ile gelen isteklerde çalışmalı;
// workflow 05'ten gelen çağrıda yanıtlanacak bir HTTP isteği yoktur.
const j = $input.first().json;
return j.webhooktan ? [{ json: j }] : [];

// İstek Telegram'dan geldiyse sonuç oraya gider.
const j = $input.first().json;
if (!j.chat_id) return [];
return [{ json: { chat_id: j.chat_id, text: String(j.mesaj).slice(0, 3900) } }];

// Yalnızca bütçe ayarı değiştiyse yazılır (limit, kelime, kategori).
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: j.butce }];

