if (h.bozuk) throw new Error('harcamalar.json okunamadı → ' + h.mesaj);

// Bütçe hiç kurulmadıysa (dosya yok) sessiz kalınır, dosya da oluşturulmaz.
if (b.yok) return [{ json: { gonderilecek: false, yazilsin: false } }];

let elle = false;
try { elle = $('Elle Test Et (Bütçe)').all().length > 0; } catch (e) { elle = false; }

const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const butce = butceyiDuzenle(b.veri);
const harcamalar = Array.isArray(h.veri.harcamalar) ? h.veri.harcamalar : [];
const simdi = new Date();
const d = durumHesapla(butce, harcamalar, simdi);

const oncekiAy = butce.uyarilar.ay;
const gonderilen = oncekiAy === d.ay ? [...butce.uyarilar.gonderilen] : [];
const uyarilar = [];
const kontrol = (ad, harcanan, limit, oran, anahtar) => {
  if (!limit) return;
  const yeni = [80, 100].filter((e) => oran >= e && !gonderilen.includes(anahtar + '-' + e));
  if (yeni.length === 0) return;
  yeni.forEach((e) => gonderilen.push(anahtar + '-' + e));
  const asti = oran >= 100;
  uyarilar.push((asti ? '🔴 ' : '🟠 ') + ad + ': ' + (asti ? 'limit aşıldı' : '%' + oran + ' doldu') +
    ' — ' + tl(harcanan) + ' / ' + tl(limit) + (asti ? '' : ', kalan ' + tl(limit - harcanan)));
};
kontrol('Genel', d.genel.harcanan, d.genel.limit, d.genel.oran, 'genel');
d.kategoriler.forEach((k) => kontrol(k.ad, k.harcanan, k.limit, k.oran, 'kat:' + kucuk(k.ad)));

const ayDegisti = oncekiAy !== d.ay;
if (uyarilar.length === 0 && !elle) {
  // Ay değiştiyse eski işaretleri sıfırlamak için yine de yazılır.
  return [{ json: { gonderilecek: false, yazilsin: ayDegisti,
    govde: { ...butce, uyarilar: { ay: d.ay, gonderilen } } } }];
}

const durum = durumMetni(d, simdi);
const text = uyarilar.length
  ? '🎯 Bütçe uyarısı\n' + uyarilar.join('\n') + (d.genel.gunlukKalan !== null && d.genel.kalan > 0
      ? '\nAy sonuna kadar günde ' + tl(d.genel.gunlukKalan) + ' harcayabilirsiniz.' : '') + '\n\n' + durum
  : durum;
return [{
  json: {
    gonderilecek: true,
    yazilsin: uyarilar.length > 0 || ayDegisti,
    text,
    konu: uyarilar.length ? '🎯 Bütçe uyarısı: ' + uyarilar.length + ' eşik' : '🎯 Bütçe durumu',
    html: '<pre style="font-family:inherit">' + esc(text) + '</pre>',
    govde: { ...butce, uyarilar: { ay: d.ay, gonderilen } },
  },
}];

// Telegram kuruluysa uyarı oraya gider; değilse bu dal boş döner.
const j = $input.first().json;
if (!j.gonderilecek) return [];
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE uyarı mail olarak gider (çift bildirim olmasın).
const j = $input.first().json;
if (!j.gonderilecek) return [];
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];

// Gönderilen eşikler işaretlenir: aynı eşik bu ay tekrar bildirilmez.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: j.govde }];
